// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {FullMath} from "@uniswap/v4-core/src/libraries/FullMath.sol";
import {FixedPoint96} from "@uniswap/v4-core/src/libraries/FixedPoint96.sol";
import {SafeCast} from "@uniswap/v4-core/src/libraries/SafeCast.sol";

/// @notice Provides functions for computing liquidity amounts from token amounts and prices
library LiquidityAmounts {
    using SafeCast for uint256;

    /// @notice Computes the amount of liquidity received for a given amount of token0 and price range
    /// @dev Calculates amount0 * (sqrt(upper) * sqrt(lower)) / (sqrt(upper) - sqrt(lower))
    /// @param sqrtPriceAX96 A sqrt price representing the first tick boundary
    /// @param sqrtPriceBX96 A sqrt price representing the second tick boundary
    /// @param amount0 The amount0 being sent in
    /// @return liquidity The amount of returned liquidity
    function getLiquidityForAmount0(uint160 sqrtPriceAX96, uint160 sqrtPriceBX96, uint256 amount0)
        internal
        pure
        returns (uint128 liquidity)
    {
        unchecked {
            if (sqrtPriceAX96 > sqrtPriceBX96) (sqrtPriceAX96, sqrtPriceBX96) = (sqrtPriceBX96, sqrtPriceAX96);
            uint256 intermediate = FullMath.mulDiv(sqrtPriceAX96, sqrtPriceBX96, FixedPoint96.Q96);
            return FullMath.mulDiv(amount0, intermediate, sqrtPriceBX96 - sqrtPriceAX96).toUint128();
        }
    }

    /// @notice Computes the amount of liquidity received for a given amount of token1 and price range
    /// @dev Calculates amount1 / (sqrt(upper) - sqrt(lower)).
    /// @param sqrtPriceAX96 A sqrt price representing the first tick boundary
    /// @param sqrtPriceBX96 A sqrt price representing the second tick boundary
    /// @param amount1 The amount1 being sent in
    /// @return liquidity The amount of returned liquidity
    function getLiquidityForAmount1(uint160 sqrtPriceAX96, uint160 sqrtPriceBX96, uint256 amount1)
        internal
        pure
        returns (uint128 liquidity)
    {
        unchecked {
            if (sqrtPriceAX96 > sqrtPriceBX96) (sqrtPriceAX96, sqrtPriceBX96) = (sqrtPriceBX96, sqrtPriceAX96);
            return FullMath.mulDiv(amount1, FixedPoint96.Q96, sqrtPriceBX96 - sqrtPriceAX96).toUint128();
        }
    }

    /// @notice Computes the maximum amount of liquidity received for a given amount of token0, token1, the current
    /// pool prices and the prices at the tick boundaries
    /// @param sqrtPriceX96 A sqrt price representing the current pool prices
    /// @param sqrtPriceAX96 A sqrt price representing the first tick boundary
    /// @param sqrtPriceBX96 A sqrt price representing the second tick boundary
    /// @param amount0 The amount of token0 being sent in
    /// @param amount1 The amount of token1 being sent in
    /// @return liquidity The maximum amount of liquidity received
    function getLiquidityForAmounts(
        uint160 sqrtPriceX96,
        uint160 sqrtPriceAX96,
        uint160 sqrtPriceBX96,
        uint256 amount0,
        uint256 amount1
    ) internal pure returns (uint128 liquidity) {
        if (sqrtPriceAX96 > sqrtPriceBX96) {
            (sqrtPriceAX96, sqrtPriceBX96) = (sqrtPriceBX96, sqrtPriceAX96);
        }

        if (sqrtPriceX96 <= sqrtPriceAX96) {
            liquidity = getLiquidityForAmount0(sqrtPriceAX96, sqrtPriceBX96, amount0);
        } else if (sqrtPriceX96 < sqrtPriceBX96) {
            uint128 liquidity0 = getLiquidityForAmount0(sqrtPriceX96, sqrtPriceBX96, amount0);
            uint128 liquidity1 = getLiquidityForAmount1(sqrtPriceAX96, sqrtPriceX96, amount1);

            liquidity = liquidity0 < liquidity1 ? liquidity0 : liquidity1;
        } else {
            liquidity = getLiquidityForAmount1(sqrtPriceAX96, sqrtPriceBX96, amount1);
        }
    }
}

src/FeeSplitter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IMainBurner {
    function buyAndBurn() external payable returns (uint256 burned);
}

/// @title FeeSplitter
/// @notice The creator fee recipient of a pool whose hook is Programmable's EthereumNative30HookV3: the kernel's fee
///         vault pays the garage's share here (anyone can call the vault's claimCreator), and sync() books what
///         arrived. With an idea contract (an agent token): 80% is the idea's, 10% the agents' work wallet's and 10%
///         the treasury's; an idea share left unclaimed for a day can be spent by anyone on buying back and burning
///         the garage's main token. Without one (the main token): half to the agents, half to the treasury.
///         Anyone can pay out; each share only goes to its own address. The treasury can change the agents' and
///         the treasury's address, so the fees can move to a new wallet if a key ever has to be rotated; nothing here
///         can change the fee or the shares.
contract FeeSplitter {
    uint256 public constant IDEA_SHARE_BPS = 8_000; // with an idea contract: 80% of the garage's share
    uint256 public constant IDEA_GRACE = 1 days; // an idea share left unclaimed this long buys and burns the main token

    address public immutable idea; // 0: no idea contract (the main token)
    address public immutable mainBurner; // the main token's MainBurner: where an idle idea share goes
    address public agents; // the agents' work wallet: compute and gas
    address public treasury;

    uint256 public ideaAccrued;
    uint256 public ideaAccruedSince; // when the oldest unclaimed idea share arrived
    uint256 public agentsAccrued;
    uint256 public treasuryAccrued;
    uint256 public ideaTotal; // booked for the idea since launch
    uint256 public mainBurned; // main tokens bought back and burned with idle idea shares
    bool private _locked;

    event Booked(uint256 toIdea, uint256 toAgents, uint256 toTreasury);
    event Paid(address indexed to, uint256 amount);
    event IdeaShareBurnedMain(uint256 ethIn, uint256 mainTokensBurned);
    event AgentsSet(address agents);
    event TreasurySet(address treasury);

    error NotTreasury();
    error InvalidAddress();
    error NothingToPay();
    error TooEarly();
    error TransferFailed();
    error Reentrant();

    modifier locked() {
        if (_locked) revert Reentrant();
        _locked = true;
        _;
        _locked = false;
    }

    constructor(address idea_, address mainBurner_, address agents_, address treasury_) {
        if (agents_ == address(0) || treasury_ == address(0) || (idea_ != address(0) && mainBurner_ == address(0))) {
            revert InvalidAddress();
        }
        idea = idea_;
        mainBurner = mainBurner_;
        agents = agents_;
        treasury = treasury_;
        emit AgentsSet(agents_);
        emit TreasurySet(treasury_);
    }

    receive() external payable {}

    /// @notice Books the ETH that arrived since the last call into the shares. Anyone can call, but not from inside a
    ///         payout: while one is under way the balance is mid-transfer and must not be booked again.
    function sync() external {
        if (_locked) revert Reentrant();
        _sync();
    }

    function _sync() private {
        uint256 owed = ideaAccrued + agentsAccrued + treasuryAccrued;
        if (address(this).balance <= owed) return;
        uint256 fresh = address(this).balance - owed;
        uint256 toIdea;
        if (idea != address(0)) {
            toIdea = fresh * IDEA_SHARE_BPS / 10_000;
            if (ideaAccrued == 0) ideaAccruedSince = block.timestamp;
            ideaAccrued += toIdea;
            ideaTotal += toIdea;
        }
        uint256 rest = fresh - toIdea;
        uint256 toAgents = rest / 2;
        agentsAccrued += toAgents;
        treasuryAccrued += rest - toAgents;
        emit Booked(toIdea, toAgents, rest - toAgents);
    }

    /// @notice Pays the agents' and the treasury's shares. Anyone can pay the gas.
    function payOut() external locked {
        _sync();
        uint256 toAgents = agentsAccrued;
        uint256 toTreasury = treasuryAccrued;
        if (toAgents + toTreasury == 0) revert NothingToPay();
        agentsAccrued = 0;
        treasuryAccrued = 0;
        _send(agents, toAgents);
        _send(treasury, toTreasury);
    }

    /// @notice Pays the idea contract its share. If its receive reverts, only this call reverts.
    function claimIdea() external locked returns (uint256 amount) {
        _sync();
        amount = ideaAccrued;
        if (amount == 0) revert NothingToPay();
        ideaAccrued = 0;
        _send(idea, amount);
    }

    /// @notice Use it or lose it: an idea share left unclaimed for IDEA_GRACE buys the main token at the market and
    ///         burns it. Anyone can call.
    function burnIdleIdeaShare() external locked returns (uint256 burned) {
        _sync();
        uint256 amount = ideaAccrued;
        if (amount == 0) revert NothingToPay();
        if (block.timestamp < ideaAccruedSince + IDEA_GRACE) revert TooEarly();
        ideaAccrued = 0;
        burned = IMainBurner(mainBurner).buyAndBurn{value: amount}();
        mainBurned += burned;
        emit IdeaShareBurnedMain(amount, burned);
    }

    function setAgents(address agents_) external {
        if (msg.sender != treasury) revert NotTreasury();
        if (agents_ == address(0)) revert InvalidAddress();
        agents = agents_;
        emit AgentsSet(agents_);
    }

    function setTreasury(address treasury_) external {
        if (msg.sender != treasury) revert NotTreasury();
        if (treasury_ == address(0)) revert InvalidAddress();
        treasury = treasury_;
        emit TreasurySet(treasury_);
    }

    function _send(address to, uint256 amount) private {
        if (amount == 0) return;
        (bool ok,) = to.call{value: amount}("");
        if (!ok) revert TransferFailed();
        emit Paid(to, amount);
    }
}

src/GarageInitializer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IHooks} from "@uniswap/v4-core/src/interfaces/IHooks.sol";
import {IPoolManager} from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import {IUnlockCallback} from "@uniswap/v4-core/src/interfaces/callback/IUnlockCallback.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {BalanceDelta} from "@uniswap/v4-core/src/types/BalanceDelta.sol";
import {StateLibrary} from "@uniswap/v4-core/src/libraries/StateLibrary.sol";
import {Currency} from "@uniswap/v4-core/src/types/Currency.sol";
import {PoolKey} from "@uniswap/v4-core/src/types/PoolKey.sol";
import {PoolIdLibrary} from "@uniswap/v4-core/src/types/PoolId.sol";
import {ModifyLiquidityParams, SwapParams} from "@uniswap/v4-core/src/types/PoolOperation.sol";
import {LiquidityAmounts} from "@uniswap/v4-periphery/src/libraries/LiquidityAmounts.sol";
import {IIdea} from "./IIdea.sol";

/// @notice What the initializer reads from the launch's hook, Programmable's EthereumNative30HookV3.
interface ILaunchHookView {
    function token() external view returns (address);
    function initializer() external view returns (address);
}

interface IBurnableToken {
    function burn(uint256 amount) external;
}

/// @title GarageInitializer
/// @notice Starts the ETH/TOKEN pool in the launch transaction: creates it at the start price and adds the whole
///         supply as a one-sided position from the minimum price up to the start price. The pool is native ETH /
///         token, LP fee 0, tick spacing 60, with the launch's hook. If the hook has an idea contract, it learns its
///         token and pool here.
///         ETH sent with the call is the launch buy, and all of it ends up in the pool: it buys the token (paying the
///         pool's fee like any buy, so its ETH is in the pool), then the tokens bought go back into the pool as a
///         second position, for sale again from the current price on. The launcher keeps nothing.
/// @dev    The positions can never be withdrawn: this contract has no owner and no function to remove liquidity.
///         Rounding dust is burned.
contract GarageInitializer is IUnlockCallback {
    using PoolIdLibrary for PoolKey;
    using StateLibrary for IPoolManager;

    uint8 private constant ADD_SUPPLY = 0;
    uint8 private constant BUY = 1;
    uint8 private constant ADD_BOUGHT = 2;
    uint24 public constant LP_FEE = 0;
    int24 public constant TICK_SPACING = 60;

    IPoolManager public immutable poolManager;

    bool public launched;
    uint128 public lockedLiquidity;
    int24 public startTick;
    uint256 public initialBuyEth; // ETH sent with the launch
    uint256 public initialBuyTokens; // tokens it bought
    uint128 public initialBuyLiquidity; // the position those tokens went back into
    int24 public initialBuyUpperTick; // its upper tick: the price right after the buy (rounded to the tick spacing)
    uint256 public initialBuyBurned; // rounding dust of those tokens

    event Launched(address indexed hook, int24 startTick, uint128 liquidity, uint256 tokensInPool, uint256 dustBurned);
    event LaunchBuyAddedToPool(uint256 ethIn, uint256 tokensBought, uint128 liquidity, uint256 tokensBurned);

    error AlreadyLaunched();
    error NotPoolManager();
    error WrongHook();
    error InvalidStartTick();
    error InvalidSettlement();

    constructor(IPoolManager manager) {
        poolManager = manager;
    }

    /// @notice Called once, by the launch factory, right after all contracts are deployed.
    /// @param hook       this launch's hook (its initializer() must point here)
    /// @param startTick_ start price tick, a multiple of the tick spacing
    function initialize(address hook, int24 startTick_) external payable {
        if (launched) revert AlreadyLaunched();
        launched = true;

        PoolKey memory key =
            PoolKey(Currency.wrap(address(0)), Currency.wrap(ILaunchHookView(hook).token()), LP_FEE, TICK_SPACING, IHooks(hook));
        if (ILaunchHookView(hook).initializer() != address(this)) revert WrongHook();
        if (
            startTick_ % key.tickSpacing != 0 || startTick_ <= TickMath.minUsableTick(key.tickSpacing)
                || startTick_ > TickMath.maxUsableTick(key.tickSpacing)
        ) revert InvalidStartTick();

        startTick = startTick_;
        poolManager.initialize(key, TickMath.getSqrtPriceAtTick(startTick_));
        poolManager.unlock(abi.encode(ADD_SUPPLY, key, startTick_, uint256(0)));

        IERC20 token = IERC20(Currency.unwrap(key.currency1));
        uint256 dust = token.balanceOf(address(this));
        if (dust != 0) IBurnableToken(address(token)).burn(dust);
        emit Launched(hook, startTick_, lockedLiquidity, token.balanceOf(address(poolManager)), dust);

        address idea = _ideaOf(hook);
        if (idea != address(0)) IIdea(idea).onLaunch(address(token), key);

        if (msg.value != 0) {
            poolManager.unlock(abi.encode(BUY, key, startTick_, msg.value));
            uint256 bought = token.balanceOf(address(this));
            poolManager.unlock(abi.encode(ADD_BOUGHT, key, startTick_, uint256(0)));
            uint256 left = token.balanceOf(address(this));
            if (left != 0) IBurnableToken(address(token)).burn(left);
            initialBuyEth = msg.value;
            initialBuyTokens = bought;
            initialBuyBurned = left;
            emit LaunchBuyAddedToPool(msg.value, bought, initialBuyLiquidity, left);
        }
    }

    /// @dev The launch's idea contract, or 0 if it has none: Programmable's kernel pays the creator fee from its vault
    ///      to the FeeSplitter, and the splitter knows the idea. Any missing link means no idea.
    function _ideaOf(address hook) private view returns (address) {
        address vault = _addressOf(hook, "feeVault()");
        address splitter = vault == address(0) ? address(0) : _addressOf(vault, "creatorRecipient()");
        return splitter == address(0) ? address(0) : _addressOf(splitter, "idea()");
    }

    function _addressOf(address target, string memory signature) private view returns (address a) {
        (bool ok, bytes memory ret) = target.staticcall(abi.encodeWithSignature(signature));
        if (ok && ret.length == 32) a = abi.decode(ret, (address));
    }

    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        if (msg.sender != address(poolManager)) revert NotPoolManager();
        (uint8 op, PoolKey memory key, int24 upper, uint256 ethIn) = abi.decode(data, (uint8, PoolKey, int24, uint256));
        if (op == BUY) return _initialBuy(key, ethIn);
        if (op == ADD_BOUGHT) return _addBought(key);

        IERC20 token = IERC20(Currency.unwrap(key.currency1));
        int24 lower = TickMath.minUsableTick(key.tickSpacing);
        // The price sits exactly at the position's upper bound, so the position is entirely in the token.
        uint128 liquidity = LiquidityAmounts.getLiquidityForAmount1(
            TickMath.getSqrtPriceAtTick(lower), TickMath.getSqrtPriceAtTick(upper), token.balanceOf(address(this))
        );
        (BalanceDelta delta,) = poolManager.modifyLiquidity(
            key, ModifyLiquidityParams(lower, upper, int256(uint256(liquidity)), bytes32(0)), ""
        );
        if (delta.amount0() != 0 || delta.amount1() >= 0) revert InvalidSettlement();

        poolManager.sync(key.currency1);
        token.transfer(address(poolManager), uint256(uint128(-delta.amount1())));
        poolManager.settle();
        lockedLiquidity = liquidity;
        return "";
    }

    /// @dev Exact-input buy for the launch ETH (msg.value is 0 inside the callback, so the amount is in data).
    ///      It pays the pool's normal fee, Programmable share included.
    function _initialBuy(PoolKey memory key, uint256 ethIn) private returns (bytes memory) {
        BalanceDelta d = poolManager.swap(key, SwapParams(true, -int256(ethIn), TickMath.MIN_SQRT_PRICE + 1), "");
        if (d.amount0() != -int256(ethIn) || d.amount1() <= 0) revert InvalidSettlement();
        poolManager.settle{value: ethIn}();
        poolManager.take(key.currency1, address(this), uint256(int256(d.amount1())));
        return "";
    }

    /// @dev The tokens bought go back into the pool: a position from the minimum price up to the current price, so it
    ///      holds the token only, like the supply position, and sells it again as the price rises. Its upper tick is
    ///      the current tick rounded down to the spacing. Unused rounding dust stays here and is burned by initialize.
    function _addBought(PoolKey memory key) private returns (bytes memory) {
        IERC20 token = IERC20(Currency.unwrap(key.currency1));
        (, int24 tick,,) = poolManager.getSlot0(key.toId());
        int24 lower = TickMath.minUsableTick(key.tickSpacing);
        int24 upper = tick / key.tickSpacing * key.tickSpacing;
        if (tick < 0 && tick % key.tickSpacing != 0) upper -= key.tickSpacing;
        if (upper <= lower) revert InvalidStartTick();
        uint128 liquidity = LiquidityAmounts.getLiquidityForAmount1(
            TickMath.getSqrtPriceAtTick(lower), TickMath.getSqrtPriceAtTick(upper), token.balanceOf(address(this))
        );
        (BalanceDelta delta,) = poolManager.modifyLiquidity(
            key, ModifyLiquidityParams(lower, upper, int256(uint256(liquidity)), bytes32(uint256(1))), ""
        );
        if (delta.amount0() != 0 || delta.amount1() >= 0) revert InvalidSettlement();

        poolManager.sync(key.currency1);
        token.transfer(address(poolManager), uint256(uint128(-delta.amount1())));
        poolManager.settle();
        initialBuyLiquidity = liquidity;
        initialBuyUpperTick = upper;
        return "";
    }
}

src/IIdea.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {PoolKey} from "@uniswap/v4-core/src/types/PoolKey.sol";

/// @notice A token's idea contract, written by an agent. It receives 80% of the garage's share of its pool fee
///         (the fee minus Programmable's 0.3%) as ETH via receive, from the FeeSplitter, and decides what to do with it.
interface IIdea {
    /// @notice Called once by the initializer right after the pool is created. The idea must check msg.sender.
    function onLaunch(address token, PoolKey calldata key) external;

    /// @notice Collect the idea's share and take its next step. Called every hour by the garage; never reverts.
    function act() external;
}

src/LaunchGuardToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC20Burnable} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";

/// @title LaunchGuardToken
/// @notice Fixed supply, no minting, no owner, no transfer taxes. The whole supply goes to the initializer, which locks
///         it in the pool forever. Fees are taken by the pool's hook (Programmable's EthereumNative30HookV3), not here.
///         Anti-sniper, in the launch block and the two after it (this token is deployed in the launch transaction,
///         so its deployment block is the launch block): a buy is a transfer out of the Uniswap v4 PoolManager. Each
///         block takes at most EARLY_BLOCK_BUYS buys, and each signing wallet (tx.origin) receives at most
///         EARLY_BUY_BPS of the supply in total, so buying through contracts, or through fresh contracts created
///         inside the transaction, still counts for the signer. Selling does not give the cap back. Both limits end
///         with the third block, whatever happened before. A buy whose tokens stay in the PoolManager as ERC-6909
///         claims is not a transfer, so these limits do not see it until the claims are redeemed.
///         The token also keeps the pool's market activity for an agent token's idea contract (stats()): buys are
///         transfers out of the PoolManager, sells transfers into it. The launch itself and the idea contract's own
///         buys are not market activity: they are neither counted nor capped.
contract LaunchGuardToken is ERC20, ERC20Burnable {
    address public constant POOL_MANAGER = 0x000000000004444c5dc75cB358380D2e3dE08A90;
    uint256 public constant EARLY_BLOCKS = 3; // the launch block and the two after it
    uint256 public constant EARLY_BLOCK_BUYS = 10; // buys per block in the window
    uint256 public constant EARLY_BUY_BPS = 200; // 2% of the supply per signing wallet in the window

    /// @notice Market activity as the token sees it. Amounts are in tokens (18 decimals); the buyer is tx.origin,
    ///         the wallet that signed the transaction.
    struct PoolStats {
        uint64 launchBlock;
        uint64 launchedAt;
        uint64 buyCount;
        uint64 sellCount;
        address lastBuyer;
        uint64 lastBuyAt;
        uint64 lastTradeAt;
        uint128 lastBuyTokens;
        uint128 buyVolume; // tokens bought
        uint128 sellVolume; // tokens sold
    }

    address public immutable initializer;
    address public immutable idea; // 0: no idea contract (the main token)
    uint256 public immutable maxEarlyBuy;
    /// @notice The launch block. Kept in storage: it is not known when the launch is packed.
    uint256 public launchBlock;
    mapping(address => uint256) public earlyBought; // tokens received from the PoolManager per signer in the window
    uint64 public blockBuysBlock; // block of the last buy in the window
    uint32 public blockBuys; // buys in that block
    PoolStats internal _stats;

    error EarlyBuyLimit();
    error BlockBuyLimit();

    constructor(string memory name_, string memory symbol_, uint256 supply, address initializer_, address idea_)
        ERC20(name_, symbol_)
    {
        initializer = initializer_;
        idea = idea_;
        maxEarlyBuy = supply * EARLY_BUY_BPS / 10_000;
        launchBlock = block.number;
        _stats.launchBlock = uint64(block.number);
        _stats.launchedAt = uint64(block.timestamp);
        _mint(initializer_, supply);
    }

    /// @notice The pool's market activity (see PoolStats).
    function stats() external view returns (PoolStats memory) {
        return _stats;
    }

    /// @notice How many tokens a wallet can still buy now; type(uint256).max once the window is over.
    function earlyBuyRemaining(address wallet) external view returns (uint256) {
        if (block.number >= launchBlock + EARLY_BLOCKS) return type(uint256).max;
        uint256 used = earlyBought[wallet];
        return used >= maxEarlyBuy ? 0 : maxEarlyBuy - used;
    }

    /// @notice Buys still allowed in this block; type(uint256).max once the window is over.
    function blockBuysRemaining() external view returns (uint256) {
        if (block.number >= launchBlock + EARLY_BLOCKS) return type(uint256).max;
        uint256 used = blockBuysBlock == uint64(block.number) ? blockBuys : 0;
        return used >= EARLY_BLOCK_BUYS ? 0 : EARLY_BLOCK_BUYS - used;
    }

    function _update(address from, address to, uint256 value) internal override {
        if (from == POOL_MANAGER && to != initializer && to != idea) _buy(value);
        else if (to == POOL_MANAGER && from != initializer && from != idea) _sell(value);
        super._update(from, to, value);
    }

    function _buy(uint256 value) private {
        if (block.number < launchBlock + EARLY_BLOCKS) {
            if (blockBuysBlock != uint64(block.number)) {
                blockBuysBlock = uint64(block.number);
                blockBuys = 0;
            }
            if (++blockBuys > EARLY_BLOCK_BUYS) revert BlockBuyLimit();
            uint256 total = earlyBought[tx.origin] + value;
            if (total > maxEarlyBuy) revert EarlyBuyLimit();
            earlyBought[tx.origin] = total;
        }
        PoolStats storage s = _stats;
        s.buyCount++;
        s.lastBuyer = tx.origin;
        s.lastBuyAt = uint64(block.timestamp);
        s.lastTradeAt = uint64(block.timestamp);
        s.lastBuyTokens = uint128(value);
        s.buyVolume += uint128(value);
    }

    function _sell(uint256 value) private {
        PoolStats storage s = _stats;
        s.sellCount++;
        s.lastTradeAt = uint64(block.timestamp);
        s.sellVolume += uint128(value);
    }
}

